<div class="product-grid"><?php foreach($products as $product):?><article class="product-card"><a class="product-photo" href="/catalog/product/<?=$product['id']?>"><img src="<?=h($product['image'])?>" alt="<?=h(tr($product))?>" width="640" height="480" loading="lazy"></a><div class="product-caption"><div><span class="eyebrow"><?=h($product['subtype_'.lang()]??'')?></span><h3><a href="/catalog/product/<?=$product['id']?>"><?=h(tr($product))?></a></h3></div><span class="price"><?=h(money((int)$product['price_minor']))?></span></div></article><?php endforeach;?></div><?php if(!$products):?><p><?=t('В этом разделе пока нет опубликованной мебели.','There is no published furniture in this section yet.')?></p><?php endif;?>
